1334	// effectAppliesToCaster is the caster-scoped sibling of effectAffectsCard:
1335	// it applies the same ConditionFn/AffectsFilter/AffectsSubtype/AffectsKeyword
1336	// checks, but keys the controller comparison (AffectsController) off an
1337	// explicit casterIdx — the player attempting to cast — rather than
1338	// card.Controller. This matters because a card being cast may not yet have
1339	// a stable battlefield Controller (it's still in hand/graveyard/exile), and
1340	// because caster-permission effects are fundamentally about WHO is casting,
1341	// not which permanent a card belongs to. AffectsSpecific/AffectsEnchanted/
1342	// ExcludeSelf are battlefield-permanent concepts and are intentionally not
1343	// consulted here.
1344	func (m *EffectManager) effectAppliesToCaster(e *ContinuousEffect, casterIdx int, spell *Card) bool {
1345		if e.ConditionFn != nil && !e.ConditionFn() {
1346			return false
1347		}
1348	
1349		if e.AffectsFilter != "" {
1350			switch e.AffectsFilter {
1351			case "creature":
1352				if !spell.IsCreature() {
1353					return false
1354				}
1355			case "land":
1356				if !spell.IsLand() {
1357					return false
1358				}
1359			case "instant":
1360				if !spell.IsInstant() {
1361					return false
1362				}
1363			case "sorcery":
1364				if !spell.IsSorcery() {
1365					return false
1366				}
1367			case "artifact":
1368				if !spell.HasType("Artifact") {
1369					return false
1370				}
1371			case "permanent":
1372				if !spell.IsPermanent() {
1373					return false
1374				}
1375			case "colorless":
1376				if !spell.IsColorless() {
1377					return false
1378				}
1379			}
1380		}
1381	
1382		if e.AffectsSubtype != "" {
1383			if strings.Contains(e.AffectsSubtype, "|") {
1384				matched := false
1385				for _, alt := range strings.Split(e.AffectsSubtype, "|") {
1386					if spell.HasSubType(strings.TrimSpace(alt)) {
1387						matched = true
1388						break
1389					}
1390				}
1391				if !matched {
1392					return false
1393				}
1394			} else if !spell.HasSubType(e.AffectsSubtype) {
1395				return false
1396			}
1397		}
1398	
1399		if e.AffectsKeyword != "" && !spell.HasKeyword(e.AffectsKeyword) {
1400			return false
1401		}
1402	
1403		effectController := e.SourceController
1404		if e.Source != nil {
1405			effectController = e.Source.Controller
1406		}
1407	
1408		if e.AffectsController != "" && e.AffectsController != "any" {
1409			switch e.AffectsController {
1410			case "you":
1411				if casterIdx != effectController {
1412					return false
1413				}
1414			case "opponent":
1415				if casterIdx == effectController {
1416					return false
1417				}
1418			}
1419		}
1420	
1421		return true
1422	}
