1424	// RedirectDamageTarget returns the actual permanent that damage aimed at
1425	// target should be applied to ([VOCAB] #54 — card-level damage redirect
1426	// hook). When target has an active RedirectDamageToPermanentID continuous
1427	// effect scoped to it via AffectsSpecific (e.g. registered by
1428	// cardfns.RedirectDamageToPermanent), the redirect destination is looked up
1429	// on m.Battlefield and returned instead; otherwise target is returned
1430	// unchanged, so every call site is a no-op absent the effect.
1431	//
1432	// Non-chaining by design: only the FIRST hop is resolved even if the new
1433	// destination itself carries its own redirect effect — a plain replacement
1434	// effect applies at most once per event (Rule 616), and this also prevents
1435	// an infinite loop between two permanents that redirect to each other.
1436	//
1437	// If the chosen destination is no longer on the battlefield (already
1438	// destroyed/exiled/bounced) or m.Battlefield is unset, the redirect is
1439	// inert for that lookup and target is returned unchanged — damage still
1440	// lands on the original permanent rather than disappearing silently.
1441	func (m *EffectManager) RedirectDamageTarget(target *Card) *Card {
1442		if m == nil || target == nil {
1443			return target
1444		}
1445		m.mu.RLock()
1446		defer m.mu.RUnlock()
1447	
1448		if m.Battlefield == nil {
1449			return target
1450		}
1451		for _, e := range m.effects {
1452			if e.RedirectDamageToPermanentID == "" {
1453				continue
1454			}
1455			if e.RedirectAllDamageFromPlayerIdx != nil {
1456				// Generic player-wide redirect ([VOCAB] #55): applies to EVERY
1457				// permanent the named player controls, not one AffectsSpecific-
1458				// scoped card, so effectAffectsCard's filter machinery is
1459				// bypassed entirely — only the controller match (and ConditionFn
1460				// gate, which effectAffectsCard would otherwise have checked)
1461				// matter here.
1462				if *e.RedirectAllDamageFromPlayerIdx != target.Controller {
1463					continue
1464				}
1465				if e.ConditionFn != nil && !e.ConditionFn() {
1466					continue
1467				}
1468			} else if !m.effectAffectsCard(e, target, target.Controller) {
1469				continue
1470			}
1471			if target.ID == e.RedirectDamageToPermanentID {
1472				continue // the redirect destination's own damage isn't redirected to itself
1473			}
1474			if redirected, err := m.Battlefield.GetCard(e.RedirectDamageToPermanentID); err == nil && redirected != nil {
1475				return redirected
1476			}
1477		}
1478		return target
1479	}
