1481	// RedirectAllDamageDestination returns the permanent to which ALL damage —
1482	// combat and noncombat alike — that playerIdx (and everything they control)
1483	// would take this turn is being redirected ([VOCAB] #55, the generic
1484	// player-wide sibling of RedirectDamageTarget's single-permanent redirect),
1485	// or nil if no such effect is currently active for playerIdx. This is the
1486	// lookup call sites use for damage aimed directly AT THE PLAYER (combat
1487	// damage from an unblocked attacker, a burn spell targeting a player, etc.);
1488	// damage aimed at one of the player's PERMANENTS instead goes through
1489	// RedirectDamageTarget, which consults the very same RedirectAllDamageFromPlayerIdx
1490	// scope so both paths stay in sync from a single registration.
1491	//
1492	// Mirrors RedirectDamageTarget's inert-when-missing guard: if the registered
1493	// destination is no longer on the battlefield (or m.Battlefield itself is
1494	// unset), this returns nil so damage lands on the player unchanged rather
1495	// than disappearing silently.
1496	func (m *EffectManager) RedirectAllDamageDestination(playerIdx int) *Card {
1497		if m == nil {
1498			return nil
1499		}
1500		m.mu.RLock()
1501		defer m.mu.RUnlock()
1502	
1503		if m.Battlefield == nil {
1504			return nil
1505		}
1506		for _, e := range m.effects {
1507			if e.RedirectDamageToPermanentID == "" || e.RedirectAllDamageFromPlayerIdx == nil {
1508				continue
1509			}
1510			if *e.RedirectAllDamageFromPlayerIdx != playerIdx {
1511				continue
1512			}
1513			if e.ConditionFn != nil && !e.ConditionFn() {
1514				continue
1515			}
1516			if redirected, err := m.Battlefield.GetCard(e.RedirectDamageToPermanentID); err == nil && redirected != nil {
1517				return redirected
1518			}
1519		}
1520		return nil
1521	}
