1523	// VictimDamageMultiplier returns the combined multiplier (>=1; 1 = no-op)
1524	// for damage about to be dealt to playerIdx — either directly to that
1525	// player's life total, or to any permanent playerIdx controls — from ANY
1526	// source ([VOCAB] #61, e.g. "Damage that would be dealt to target player and
1527	// permanents they control this turn is doubled instead"). This is keyed on
1528	// the damage RECIPIENT, unlike every source-scoped multiplier elsewhere in
1529	// the engine (DamageMultiplier/YourDamageMultiplier/DamageMultiplierSelf/
1530	// EOTDamageMultipliers) — see ContinuousEffect.VictimDamageMultiplierPlayerIdx
1531	// for the full rationale. Call-site convention: callers multiply this
1532	// on top of the amount ModifyDamageAmount/ModifyDamageAmountBetween/
1533	// ApplyEOTDamageMultiplier already produced from the source side, so a
1534	// simultaneously-active source-side doubler and this victim-side doubler
1535	// compose to a quadrupling rather than either one silently winning.
1536	//
1537	// Multiple simultaneously-active victim-scoped effects for the SAME
1538	// playerIdx also compose multiplicatively (mirrors RedirectAllDamageDestination's
1539	// single-registration-wins semantics being the exception, not the rule, for
1540	// the multiplier fields in this file — see DamageDealtMultiplier/
1541	// DamageReceivedMultiplier's identical multiply-in-sequence convention).
1542	//
1543	// Returns 1 if m is nil or no matching effect is currently active for
1544	// playerIdx.
1545	func (m *EffectManager) VictimDamageMultiplier(playerIdx int) int {
1546		if m == nil {
1547			return 1
1548		}
1549		m.mu.RLock()
1550		defer m.mu.RUnlock()
1551	
1552		mult := 1
1553		for _, e := range m.effects {
1554			if e.VictimDamageMultiplier <= 1 || e.VictimDamageMultiplierPlayerIdx == nil {
1555				continue
1556			}
1557			if *e.VictimDamageMultiplierPlayerIdx != playerIdx {
1558				continue
1559			}
1560			if e.ConditionFn != nil && !e.ConditionFn() {
1561				continue
1562			}
1563			mult *= e.VictimDamageMultiplier
1564		}
1565		return mult
1566	}
