1592	// effectAffectsCard checks if an effect applies to a specific card
1593	// The sourceControllerIdx parameter is kept for backwards compatibility but
1594	// the effect's SourceController field is preferred if set
1595	func (m *EffectManager) effectAffectsCard(e *ContinuousEffect, card *Card, sourceControllerIdx int) bool {
1596		if card == nil {
1597			return false
1598		}
1599	
1600		// Conditional ("as long as …") effects: this single check gates every
1601		// apply path (power, toughness, keyword grants).
1602		if e.ConditionFn != nil && !e.ConditionFn() {
1603			return false
1604		}
1605	
1606		// If effect targets a specific card, check that first
1607		if e.AffectsSpecific != "" {
1608			return e.AffectsSpecific == card.ID
1609		}
1610	
1611		// Aura "enchanted permanent" effects apply only to the permanent the source is attached to
1612		if e.AffectsEnchanted {
1613			if e.Source == nil || e.Source.AttachedTo == "" {
1614				return false
1615			}
1616			return card.ID == e.Source.AttachedTo
1617		}
1618	
1619		// Check exclude self
1620		if e.ExcludeSelf && e.SourceID == card.ID {
1621			return false
1622		}
1623	
1624		// Check filter (creature, permanent, etc.)
1625		if e.AffectsFilter != "" {
1626			switch e.AffectsFilter {
1627			case "creature":
1628				if !card.IsCreature() {
1629					return false
1630				}
1631			case "permanent":
1632				if !card.IsPermanent() {
1633					return false
1634				}
1635			case "land":
1636				if !card.IsLand() {
1637					return false
1638				}
1639			// task 2370 (static_subject): TYPE+creature AND-compounds ("other
1640			// artifact creatures you control have haste" — Alibou, Urza Chief
1641			// Artificer; "land creatures you control get +1/+1" — Blossoming
1642			// Tortoise, Tatyova). A single AffectsFilter string can't express an
1643			// AND of two card types the way AffectsSubtype expresses an OR via
1644			// "|", so each compound gets its own case rather than trying to
1645			// generalize the string format.
1646			case "artifact_creature":
1647				if !card.HasType("Artifact") || !card.IsCreature() {
1648					return false
1649				}
1650			case "enchantment_creature":
1651				if !card.HasType("Enchantment") || !card.IsCreature() {
1652					return false
1653				}
1654			case "land_creature":
1655				if !card.IsLand() || !card.IsCreature() {
1656					return false
1657				}
1658			}
1659		}
1660	
1661		// Check subtype — supports "|"-joined alternatives (e.g. "Wolf|Werewolf").
1662		// "chosen_creature_type" is a placeholder (Metallic Mimic, Patchwork
1663		// Banner) for a type picked via an ETB choice — resolve it against the
1664		// SOURCE's own live ChosenCreatureType rather than matching the literal
1665		// string (no card is ever printed with that subtype).
1666		if e.AffectsSubtype != "" {
1667			subtype := e.AffectsSubtype
1668			if subtype == "chosen_creature_type" {
1669				if e.Source == nil || e.Source.ChosenCreatureType == "" {
1670					return false
1671				}
1672				subtype = e.Source.ChosenCreatureType
1673			}
1674			if strings.Contains(subtype, "|") {
1675				matched := false
1676				for _, alt := range strings.Split(subtype, "|") {
1677					if card.HasSubType(strings.TrimSpace(alt)) {
1678						matched = true
1679						break
1680					}
1681				}
1682				if !matched {
1683					return false
1684				}
1685			} else if !card.HasSubType(subtype) {
1686				return false
1687			}
1688		}
1689	
1690		// Negative gates (task 2008): "each other non-Human creature you
1691		// control" / "each other nontoken creature you control".
1692		if e.AffectsExcludeSubtype != "" && card.HasSubType(e.AffectsExcludeSubtype) {
1693			return false
1694		}
1695		if e.AffectsNontoken && card.IsToken {
1696			return false
1697		}
1698		if e.AffectsToken && !card.IsToken {
1699			return false
1700		}
1701		// task 2370 (static_subject): "creatures you control with +1/+1
1702		// counters on them" (Agatha's Soul Cauldron, Sphere Grid) / "each
1703		// creature you control with a counter on it" (Cathedral Acolyte, "any"
1704		// sentinel — no specific counter type named). Mirrors CountCounterType's
1705		// "any" handling (evaluatePerCount above) rather than treating "any" as
1706		// a literal counter type name.
1707		if e.AffectsCounterType != "" {
1708			if e.AffectsCounterType == "any" {
1709				if !card.Counters.HasCounters() {
1710					return false
1711				}
1712			} else if card.Counters.GetCount(CounterType(e.AffectsCounterType)) == 0 {
1713				return false
1714			}
1715		}
1716	
1717		// Check color — matches Card.HasColor (the card's own printed/derived
1718		// color, deliberately not the effects-aware variant to avoid recursing
1719		// back into this same EffectManager's Layer 5 color grants).
1720		if e.AffectsColor != "" && !card.HasColor(e.AffectsColor) {
1721			return false
1722		}
1723		if e.AffectsExcludeColor != "" && card.HasColor(e.AffectsExcludeColor) {
1724			return false
1725		}
1726		if e.AffectsColorless && !card.IsColorless() {
1727			return false
1728		}
1729		if e.AffectsLegendary && !card.Legendary {
1730			return false
1731		}
1732		if e.AffectsAttacking && !card.Attacking {
1733			return false
1734		}
1735		if e.AffectsBlocking && !card.Blocking {
1736			return false
1737		}
1738		if e.AffectsModified && !isModifiedPermanent(m, card) {
1739			return false
1740		}
1741		if e.AffectsTapped && !card.Tapped {
1742			return false
1743		}
1744		if e.AffectsUntapped && card.Tapped {
1745			return false
1746		}
1747		if e.AffectsMulticolored {
1748			colorCount := 0
1749			for _, color := range []Color{White, Blue, Black, Red, Green} {
1750				if card.HasColor(color) {
1751					colorCount++
1752				}
1753			}
1754			if colorCount < 2 {
1755				return false
1756			}
1757		}
1758		if e.AffectsCommander && !card.IsCommander {
1759			return false
1760		}
1761	
1762		// Check the arbitrary predicate escape hatch, if set.
1763		if e.AffectsPredicateFn != nil && !e.AffectsPredicateFn(card) {
1764			return false
1765		}
1766	
1767		// Check controller - use effect's SourceController if available
1768		effectController := e.SourceController
1769		if effectController == 0 && e.Source != nil {
1770			effectController = e.Source.Controller
1771		}
1772	
1773		if e.AffectsController != "" && e.AffectsController != "any" {
1774			switch e.AffectsController {
1775			case "you":
1776				if card.Controller != effectController {
1777					return false
1778				}
1779			case "opponent":
1780				if card.Controller == effectController {
1781					return false
1782				}
1783			}
1784		}
1785	
1786		if e.AffectsKeyword != "" && !card.HasKeyword(e.AffectsKeyword) {
1787			return false
1788		}
1789	
1790		return true
1791	}
