- Pattern definition: `/opt/development/test/openmagic/backend/cards/patterns_complex.go:1318-1342`
```go
// patternDiscardCardSwitchPowerToughnessSelf matches activated abilities whose
// cost is discarding a card and whose effect is switching this creature's power
// and toughness until end of turn.
// Example: "Discard a card: Switch this creature's power and toughness until end of turn." (Aquamoeba)
func patternDiscardCardSwitchPowerToughnessSelf() *Pattern {
    return &Pattern{
        ID:          "discard_card_switch_power_toughness_self",
        ...
        Regex:       regexp.MustCompile(`(?i)^Discard a card:\s*Switch this creature's power and toughness until end of turn\.?$`),
        Priority:    45,
        Template: func(matches []string, cardType string) []AbilityDSL {
            return []AbilityDSL{
                {
                    Type:   "activated",
                    Effect: "switch_power_toughness",
                    Cost:   &AbilityCost{DiscardN: 1},
                },
            }
        },
    }
}
```
