// Package game implements core MTG game objects according to the Comprehensive Rules
package game

import (
	"strings"
	"sync"
	"time"
)

// ContinuousEffect represents an active continuous effect on the battlefield
// Rule 611 - Continuous Effects
type ContinuousEffect struct {
	ID               string `json:"id"`
	Source           *Card  `json:"-"` // The card generating this effect
	SourceID         string `json:"source_id"`
	SourceController int    `json:"source_controller"` // Controller of the source when effect was created
	Timestamp        int64  `json:"timestamp"`         // For ordering (Rule 613.7)

	// ConditionFn gates conditional ("as long as …") effects: when set and it
	// returns false, the effect applies to nothing. Evaluated live on every
	// application, so the effect switches on/off with the game state.
	// Not serialized — a rebuilt game re-registers effects via card handlers.
	ConditionFn func() bool `json:"-"`

	// RuntimeCondition is the v2 "as long as …" static condition (schema-v2
	// Change 2, re-parse R0c: static_conditional), precomputed at conversion
	// time from AbilityDSL.Condition via ConvertCondition. It carries no
	// closure, so it survives copying/inspection; GameState.RegisterCardAbilities
	// is what turns it into a live ConditionFn (mirrors TriggeredAbility.
	// RuntimeCondition/EvaluateCondition, extended here to gate continuous
	// effects instead of trigger-time checks).
	RuntimeCondition *ConditionSpec `json:"-"`

	// What is being modified
	PowerMod     int  `json:"power_mod,omitempty"`
	ToughnessMod int  `json:"toughness_mod,omitempty"`
	SetPower     *int `json:"set_power,omitempty"`     // For "becomes X/Y" effects
	SetToughness *int `json:"set_toughness,omitempty"` // For "becomes X/Y" effects

	// DynamicPowerMod / DynamicToughnessMod are pointer-backed additive
	// modifiers (Layer 7c). Unlike the fixed PowerMod/ToughnessMod ints,
	// these are mutated live inside ConditionFn by a closure that
	// recomputes the boost from live game state — the same pattern
	// SetPower/SetToughness use for CDAs, but for additive boosts.
	// Not serialized (closures aren't JSON-safe).
	DynamicPowerMod     *int `json:"-"`
	DynamicToughnessMod *int `json:"-"`

	GrantKeyword Keyword `json:"grant_keyword,omitempty"`

	// EtbCounterGrant, when non-nil, marks this static ability as putting
	// additional counters on OTHER qualifying permanents as THEY enter the
	// battlefield (Rule 614.12 replacement effect keyed off a filter) — e.g.
	// Gev, Scaled Scorch: "Other creatures you control enter with an
	// additional +1/+1 counter ... for each opponent who lost life this
	// turn", Metallic Mimic: "... of the chosen type enter with an
	// additional +1/+1 counter", Tayam, Luminous Enigma: "Each other
	// creature you control enters with an additional vigilance counter".
	// Distinct from Card.EtbCounters (fires only for the card's OWN entry):
	// this is consulted via EffectManager.GetEffectsAffecting for every

	// "this ContinuousEffect isn't one of these." Consulted by
	// EffectManager.VictimDamageMultiplier, which callers multiply on top of
	// whatever source-side multiplier (ModifyDamageAmount/
	// ModifyDamageAmountBetween/ApplyEOTDamageMultiplier) already produced —
	// both apply, composed multiplicatively, matching how every other pair of
	// simultaneously-active multipliers in this engine already stacks rather
	// than one silently overriding the other.
