// EffectManager manages all active continuous effects
// Thread-safe for concurrent access
type EffectManager struct {
	mu          sync.RWMutex
	effects     []*ContinuousEffect
	counter     int64      // For generating unique IDs
	Battlefield *Zone      `json:"-"` // Reference to battlefield for evaluating variable modifiers
	Game        *GameState `json:"-"` // Back-pointer to GameState so evaluatePerCount can delegate CountSpec to EvalDynamicAmount (task-2365: graveyard/hand/opponents count sources for pump_per_count)
}

// NewEffectManager creates a new EffectManager instance
func NewEffectManager() *EffectManager {
	return &EffectManager{
		effects: make([]*ContinuousEffect, 0),
	}
}

// Register adds a new continuous effect
func (m *EffectManager) Register(e *ContinuousEffect) {
	m.mu.Lock()
	defer m.mu.Unlock()

	// Assign ID and timestamp if not set
	if e.ID == "" {
		m.counter++
		e.ID = generateEffectID(m.counter)
	}
	if e.Timestamp == 0 {
		e.Timestamp = time.Now().UnixNano()
	}
	if e.Source != nil {
		e.SourceID = e.Source.ID
		e.SourceController = e.Source.Controller
	}
	// Default layer for effect modifications (Rule 613)
	if e.Layer == "" {
		if e.StripAbilities {
			e.Layer = "6" // Layer 6: ability-removing effects
		} else if e.SetPower != nil || e.SetToughness != nil {
			e.Layer = "7b"
		} else if e.PowerMod != 0 || e.ToughnessMod != 0 ||
			e.DynamicPowerMod != nil || e.DynamicToughnessMod != nil {
			e.Layer = "7c"
		} else if e.AddType != "" || len(e.SetSubTypes) > 0 || e.AddSubType != "" {
			e.Layer = "4"
		} else if len(e.SetColors) > 0 || e.AddColor != "" {
			e.Layer = "5"
		}
	}

	m.effects = append(m.effects, e)
}

