	if e.ExcludeSelf && e.SourceID == card.ID {
		return false
	}

	// Check filter (creature, permanent, etc.)
	if e.AffectsFilter != "" {
		switch e.AffectsFilter {
		case "creature":
			if !card.IsCreature() {
				return false
			}
		case "permanent":
			if !card.IsPermanent() {
				return false
			}
		case "land":
